from itertools import combinations
import heapq


def _dependency_solver(data, direction):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    best_vector = None
    best_install = None

    def visit(chosen, constraints, edges):
        nonlocal best_vector, best_install
        # All constrained packages have been assigned: this is one installation.
        todo = [name for name in constraints if name not in chosen]
        if not todo:
            vector = tuple(chosen.get(name, -1) for name in names)
            if best_vector is None or direction * (vector_compare(vector, best_vector)) > 0:
                best_vector = vector
                best_install = dict(chosen)
            return

        name = min(todo)
        low, high = constraints[name]
        rows = [row for row in packages[name]
                if low <= row["version"] <= high
                and row["version"] not in blocked.get(name, [])
                and (name not in pins or row["version"] == pins[name])]
        for row in rows:
            version = row["version"]
            new_chosen = dict(chosen)
            new_chosen[name] = version
            new_constraints = dict(constraints)
            new_edges = {key: set(value) for key, value in edges.items()}
            new_edges.setdefault(name, set())
            valid = True
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                lo, hi = dep["min"], dep["max"]
                if target in new_constraints:
                    old_lo, old_hi = new_constraints[target]
                    lo, hi = max(lo, old_lo), min(hi, old_hi)
                if lo > hi:
                    valid = False
                    break
                new_constraints[target] = (lo, hi)
                new_edges[name].add(target)
            if not valid:
                continue
            # Reject directed cycles, including a self-dependency.
            active, done = set(), set()
            def acyclic(node):
                if node in active:
                    return False
                if node in done:
                    return True
                active.add(node)
                for nxt in new_edges.get(node, ()):
                    if not acyclic(nxt):
                        return False
                active.remove(node)
                done.add(node)
                return True
            if not all(acyclic(node) for node in new_edges):
                continue
            if any(chosen_name in new_constraints and
                   not new_constraints[chosen_name][0] <= chosen_version <= new_constraints[chosen_name][1]
                   for chosen_name, chosen_version in new_chosen.items()):
                continue
            visit(new_chosen, new_constraints, new_edges)

    def vector_compare(a, b):
        return (a > b) - (a < b)

    constraints = {name: tuple(bounds) for name, bounds in data["roots"].items()}
    visit({}, constraints, {})
    if best_install is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_install}


def _component_01(data):
    return _dependency_solver(data, -1)


def _component_02(data):
    return _dependency_solver(data, 1)


