def _component_06(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (sequence, event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(numerator, denominator=10000):
        if mode == "half_up":
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(net * event.get("tax_bp", 0))
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        account = event.get("account", "default")
        currency = event.get("currency", "USD")
        key = account + "|" + currency
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _component_07(data):
    jobs = [job for job in data["jobs"]
            if job["id"] not in data.get("blocked", [])]
    k = data["k"]
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_ids = None
    best_value = None

    for subset in combinations(jobs, k):
        ids = sorted(job["id"] for job in subset)
        id_set = set(ids)
        if not mandatory.issubset(id_set):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not (bounds[0] <= counts.get(group, 0) <= bounds[1])
               for group, bounds in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda job: (job["start"], job["end"], job["id"]))
        if any(ordered[i]["start"] < ordered[i - 1]["end"]
               for i in range(1, len(ordered))):
            continue
        value = sum(job["value"] for job in subset)
        if (best_value is None or value > best_value or
                (value == best_value and ids < best_ids)):
            best_value, best_ids = value, ids
    if best_ids is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _component_08(data):
    required = data.get("required", [])
    full_mask = (1 << len(required)) - 1
    visit_bit = {}
    for i, node in enumerate(required):
        visit_bit[node] = visit_bit.get(node, 0) | (1 << i)
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = visit_bit.get(source, 0)
    initial = (source, initial_mask, data["coupons"])
    distances = {initial: data["start"]}
    queue = [(data["start"], source, initial_mask, data["coupons"])]
    while queue:
        arrival, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != arrival:
            continue
        if node == data["target"] and mask == full_mask and remaining == 0:
            return {"arrival": arrival}
        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            durations = [(edge["duration"], remaining)]
            if remaining:
                duration = max(2, edge["duration"] - edge.get("discount", 0))
                durations.append((duration, remaining - 1))
            for duration, next_remaining in durations:
                next_time = depart + duration
                if next_time > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | visit_bit.get(next_node, 0)
                next_state = (next_node, next_mask, next_remaining)
                if next_time < distances.get(next_state, float("inf")):
                    distances[next_state] = next_time
                    heapq.heappush(queue, (next_time, next_node, next_mask, next_remaining))
    return {"arrival": None}


SOLVERS = {
    "component_01": _component_01,
    "component_02": _component_02,
    "component_03": _component_03,
    "component_04": _component_04,
    "component_05": _component_05,
    "component_06": _component_06,
    "component_07": _component_07,
    "component_08": _component_08,
}

